    EndOfStream,
    InvalidInternalReplicationRequest,
    InternalReplicationEndpointNotFound,
    UnsupportedOperation,
    InternalReplicationConflict,
    InternalReplicationEndpointNotReady,
    SlotNotFound,
    UnexpectedHttpStatus,
    NotListening,
    UnsupportedReplicationFormat,
    ReplicationResponseLsnMismatch,
    ReplicationResponseEndOfWalMismatch,
    ReplicationFrameLsnMismatch,
    UnexpectedRecordLsn,
    UnexpectedPreviousLsn,
