pub const StoreRegistrationConfig = struct {
    node_id: u64,
    store_id: u64,
    api_url: []const u8 = "",
    raft_url: []const u8 = "",
    role: []const u8 = "data",
    failure_domain: []const u8 = "",
};

pub const GroupLeadershipSource = struct {
    ptr: *anyopaque,
    vtable: *const VTable,

    pub const VTable = struct {
        is_local_leader: *const fn (ptr: *anyopaque, group_id: u64) bool,
        current_epoch: ?*const fn (ptr: *anyopaque, group_id: u64) ?u64 = null,
    };

    pub fn isLocalLeader(self: GroupLeadershipSource, group_id: u64) bool {
        return self.vtable.is_local_leader(self.ptr, group_id);
    }

    pub fn currentEpoch(self: GroupLeadershipSource, group_id: u64) ?u64 {
        const current_epoch = self.vtable.current_epoch orelse return null;
        return current_epoch(self.ptr, group_id);
    }

    pub fn fromManagedHostService(service: *antfly.raft.ManagedHostService) GroupLeadershipSource {
        return .{
            .ptr = service,
            .vtable = &.{
                .is_local_leader = struct {
                    fn isLocalLeader(ptr: *anyopaque, group_id: u64) bool {
                        const svc: *antfly.raft.ManagedHostService = @ptrCast(@alignCast(ptr));
                        return svc.host.host.isLocalLeader(group_id);
                    }
                }.isLocalLeader,
                .current_epoch = struct {
                    fn currentEpoch(ptr: *anyopaque, group_id: u64) ?u64 {
                        const svc: *antfly.raft.ManagedHostService = @ptrCast(@alignCast(ptr));
                        const status = svc.host.host.raftStatus(group_id) orelse return null;
                        return status.hard.current_term;
                    }
                }.currentEpoch,
            },
        };
    }

    pub fn fromManagedHttpHostService(service: *antfly.raft.ManagedHttpHostService) GroupLeadershipSource {
        return .{
            .ptr = service,
            .vtable = &.{
                .is_local_leader = struct {
                    fn isLocalLeader(ptr: *anyopaque, group_id: u64) bool {
                        const svc: *antfly.raft.ManagedHttpHostService = @ptrCast(@alignCast(ptr));
                        return svc.host.http_host.host.isLocalLeader(group_id);
                    }
                }.isLocalLeader,
                .current_epoch = struct {
                    fn currentEpoch(ptr: *anyopaque, group_id: u64) ?u64 {
                        const svc: *antfly.raft.ManagedHttpHostService = @ptrCast(@alignCast(ptr));
                        const status = svc.host.http_host.host.raftStatus(group_id) orelse return null;
                        return status.hard.current_term;
                    }
                }.currentEpoch,
            },
        };
    }
};

const IndexRepairOwnershipFence = struct {
    leadership_source: ?GroupLeadershipSource,
    write_source: *antfly.public_api.table_writes.ProvisionedTableWriteSource,
    group_id: u64,
    root_generation: u64,
    owner_epoch: u64,

    fn currentOwnerEpoch(self: *const @This()) u64 {
        if (self.leadership_source) |source| {
            if (source.currentEpoch(self.group_id)) |epoch| return epoch;
        }
        // The visible root generation is the strongest monotonic fence
        // available to deployments without a Raft term source.
        return self.write_source.visibleRootGenerationForRepair(self.group_id);
    }

    fn isCurrentOwner(ptr: *anyopaque) anyerror!bool {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        if (self.write_source.visibleRootGenerationForRepair(self.group_id) != self.root_generation) return false;
        if (self.currentOwnerEpoch() != self.owner_epoch) return false;
        const source = self.leadership_source orelse return true;
        // Activation is intentionally stricter than discovery. Snapshot
        // placement can admit inspection while leadership is converging, but
        // a replacement pointer may only be published by the live leader.
        return source.isLocalLeader(self.group_id);
    }
};

const IndexRepairCancellationFence = struct {
    server: *DataServer,
    group_id: u64,

    fn requested(ptr: *anyopaque) bool {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        return self.server.provisioned_index_repair_shutdown.load(.acquire) or
            self.server.provisionedIndexRepairCancellationRequested(self.group_id);
    }
};

const IndexRepairYieldFence = struct {
    deadline_ns: u64,

    fn requested(ptr: *anyopaque) bool {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        return platform_time.monotonicNs() >= self.deadline_ns;
    }
};

pub const GroupMembership = struct {
    local_leader: bool = false,
    leadership_known: bool = false,
    local_voter: bool = false,
    voter_count: u16 = 0,
    voter_set_known: bool = false,
    voter_set_fingerprint: antfly.metadata.table_manager.VoterSetFingerprint = [_]u8{0} ** antfly.metadata.table_manager.voter_set_fingerprint_len,
    joint_consensus: bool = false,
    raft_term: u64 = 0,
    raft_membership_index: u64 = 0,
};

pub const GroupMembershipSource = struct {
    ptr: *anyopaque,
    vtable: *const VTable,

    pub const VTable = struct {
        membership: *const fn (ptr: *anyopaque, group_id: u64) GroupMembership,
    };

    pub fn membership(self: GroupMembershipSource, group_id: u64) GroupMembership {
        return self.vtable.membership(self.ptr, group_id);
    }

    pub fn fromManagedHostService(service: *antfly.raft.ManagedHostService) GroupMembershipSource {
        return .{
            .ptr = service,
            .vtable = &.{
                .membership = struct {
                    fn membership(ptr: *anyopaque, group_id: u64) GroupMembership {
                        const svc: *antfly.raft.ManagedHostService = @ptrCast(@alignCast(ptr));
                        const raft_status = svc.host.host.raftStatus(group_id) orelse return .{};
                        var local_voter = false;
                        for (raft_status.conf_state.voters) |node_id| {
                            if (node_id == svc.host.host.cfg.local_node_id) {
                                local_voter = true;
                                break;
                            }
                        }
                        return .{
                            .local_leader = raft_status.soft.role == .leader and
                                raft_status.soft.leader_id == raft_status.id,
                            .leadership_known = true,
                            .local_voter = local_voter,
                            .voter_count = @intCast(raft_status.conf_state.voters.len),
                            .voter_set_known = true,
                            .voter_set_fingerprint = antfly.metadata.table_manager.voterSetFingerprint(raft_status.conf_state.voters, null),
                            .joint_consensus = raft_status.conf_state.voters_outgoing.len > 0,
                            .raft_term = raft_status.hard.current_term,
                            .raft_membership_index = raft_status.applied_index,
                        };
                    }
                }.membership,
            },
        };
    }

    pub fn fromManagedHttpHostService(service: *antfly.raft.ManagedHttpHostService) GroupMembershipSource {
        return .{
            .ptr = service,
            .vtable = &.{
                .membership = struct {
                    fn membership(ptr: *anyopaque, group_id: u64) GroupMembership {
                        const svc: *antfly.raft.ManagedHttpHostService = @ptrCast(@alignCast(ptr));
                        const raft_status = svc.host.http_host.host.raftStatus(group_id) orelse return .{};
                        var local_voter = false;
                        for (raft_status.conf_state.voters) |node_id| {
                            if (node_id == svc.host.http_host.host.cfg.local_node_id) {
                                local_voter = true;
                                break;
                            }
                        }
                        return .{
                            .local_leader = raft_status.soft.role == .leader and
                                raft_status.soft.leader_id == raft_status.id,
                            .leadership_known = true,
                            .local_voter = local_voter,
                            .voter_count = @intCast(raft_status.conf_state.voters.len),
                            .voter_set_known = true,
                            .voter_set_fingerprint = antfly.metadata.table_manager.voterSetFingerprint(raft_status.conf_state.voters, null),
                            .joint_consensus = raft_status.conf_state.voters_outgoing.len > 0,
                            .raft_term = raft_status.hard.current_term,
                            .raft_membership_index = raft_status.applied_index,
                        };
                    }
                }.membership,
            },
        };
    }
};

fn observedLocalGroupLeader(
    membership: GroupMembership,
    leadership_source: ?GroupLeadershipSource,
    group_id: u64,
    fallback: bool,
) bool {
    // Managed membership sources bind role, term, membership, and apply index
    // to one Raft status snapshot. Custom sources can retain the legacy
    // leadership callback by leaving `leadership_known` false.
    if (membership.leadership_known) return membership.local_leader;
    if (leadership_source) |source| return source.isLocalLeader(group_id);
    return fallback;
}

test "group status binds leadership to the membership Raft snapshot" {
    const Leadership = struct {
        fn source() GroupLeadershipSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .is_local_leader = struct {
                        fn call(_: *anyopaque, _: u64) bool {
                            return true;
                        }
                    }.call,
                },
            };
        }
    };
    try std.testing.expect(!observedLocalGroupLeader(
        .{ .leadership_known = true, .local_leader = false },
        Leadership.source(),
        1,
        false,
    ));
    try std.testing.expect(observedLocalGroupLeader(
        .{},
        Leadership.source(),
        1,
        false,
    ));
}

test "index repair queue removes only authoritative non-local ownership" {
    const Ownership = struct {
        const Self = @This();

        leader: bool = false,
        membership: GroupMembership = .{},

        fn leadership(self: *Self) GroupLeadershipSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .is_local_leader = struct {
                        fn call(ptr: *anyopaque, _: u64) bool {
                            const ctx: *Self = @ptrCast(@alignCast(ptr));
                            return ctx.leader;
                        }
                    }.call,
                },
            };
        }

        fn memberships(self: *Self) GroupMembershipSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .membership = struct {
                        fn call(ptr: *anyopaque, _: u64) GroupMembership {
                            const ctx: *Self = @ptrCast(@alignCast(ptr));
                            return ctx.membership;
                        }
                    }.call,
                },
            };
        }
    };

    var ownership = Ownership{};
    try std.testing.expectEqual(
        DataServer.StartupCatchUpGroupDisposition.retry_unknown,
        DataServer.queuedRepairLiveOwnershipDisposition(ownership.leadership(), ownership.memberships(), 7),
    );
    ownership.membership = .{ .voter_set_known = true, .local_voter = true };
    try std.testing.expectEqual(
        DataServer.StartupCatchUpGroupDisposition.retry_unknown,
        DataServer.queuedRepairLiveOwnershipDisposition(ownership.leadership(), ownership.memberships(), 7),
    );
    ownership.membership.local_voter = false;
    try std.testing.expectEqual(
        DataServer.StartupCatchUpGroupDisposition.skip_nonlocal,
        DataServer.queuedRepairLiveOwnershipDisposition(ownership.leadership(), ownership.memberships(), 7),
    );
    ownership.leader = true;
    try std.testing.expectEqual(
        DataServer.StartupCatchUpGroupDisposition.attempt,
        DataServer.queuedRepairLiveOwnershipDisposition(ownership.leadership(), ownership.memberships(), 7),
    );
}

const InferredSnapshotLeadershipSource = struct {
    local_node_id: u64,
    local_store_id: u64,
    stores: []const antfly.metadata.StoreRecord,
    merged_group_statuses: []const antfly.metadata.reconciler.MergedGroupStatus,
    placement_intents: []const antfly.raft.reconciler.PlacementIntent,

    fn init(
        local_node_id: u64,
        local_store_id: u64,
        stores: []const antfly.metadata.StoreRecord,
        merged_group_statuses: []const antfly.metadata.reconciler.MergedGroupStatus,
        placement_intents: []const antfly.raft.reconciler.PlacementIntent,
    ) InferredSnapshotLeadershipSource {
        return .{
            .local_node_id = local_node_id,
            .local_store_id = local_store_id,
            .stores = stores,
            .merged_group_statuses = merged_group_statuses,
            .placement_intents = placement_intents,
        };
    }

    fn iface(self: *const InferredSnapshotLeadershipSource) GroupLeadershipSource {
        return .{
            .ptr = @constCast(self),
            .vtable = &.{
                .is_local_leader = isLocalLeader,
            },
        };
    }

    fn isLocalLeader(ptr: *anyopaque, group_id: u64) bool {
        const self: *const InferredSnapshotLeadershipSource = @ptrCast(@alignCast(ptr));
        if (self.explicitLeaderStoreId(group_id)) |leader_store_id| {
            return leader_store_id == self.local_store_id;
        }
        if (self.stores.len == 1 and self.stores[0].store_id == self.local_store_id) return true;

        var placement_count: usize = 0;
        var local_match = false;
        for (self.placement_intents) |intent| {
            if (intent.record.group_id != group_id) continue;
            placement_count += 1;
            if (intent.record.local_node_id == self.local_node_id or intent.store_id == self.local_store_id) {
                local_match = true;
            }
        }
        return placement_count == 1 and local_match;
    }

    fn explicitLeaderStoreId(self: *const InferredSnapshotLeadershipSource, group_id: u64) ?u64 {
        if (findMergedSnapshotGroupStatus(self.merged_group_statuses, group_id)) |status| {
            if (status.leader_known) return status.leader_store_id;
            return null;
        }
        var leader_store_id: ?u64 = null;
        for (self.stores) |store| {
            if (!store.live) continue;
            if (!std.mem.eql(u8, store.health_class, "healthy")) continue;
            for (store.group_statuses) |group_status| {
                if (group_status.group_id != group_id) continue;
                if (!group_status.local_leader) continue;
                if (leader_store_id == null) {
                    leader_store_id = store.store_id;
                    continue;
                }
                if (leader_store_id.? != store.store_id) return null;
            }
        }
        return leader_store_id;
    }
};

const TransitionDbLeaseContext = struct {
    const Owner = union(enum) {
        cached: antfly.public_api.ProvisionedTableWriteCache.CachedDb,
        owned: antfly.db.DB,
    };

    alloc: std.mem.Allocator,
    activity: antfly.public_api.ProvisionedTableWriteSource.GroupTransitionActivity,
    owner: Owner,

    fn db(self: *TransitionDbLeaseContext) *antfly.db.DB {
        return switch (self.owner) {
            .cached => |*cached| cached.db,
            .owned => |*owned_db| owned_db,
        };
    }

    fn release(ptr: *anyopaque) void {
        const self: *TransitionDbLeaseContext = @ptrCast(@alignCast(ptr));
        switch (self.owner) {
            .cached => |*cached| cached.deinit(self.alloc),
            .owned => |*owned_db| owned_db.close(),
        }
        self.activity.deinit();
        self.alloc.destroy(self);
    }
};

const RaftBatchLeaderStatusDiagnostics = struct {
    node_id: u64,
    role: raft_engine.core.types.StateRole,
    leader_id: ?u64,
    voter_count: usize,
    term: u64,
    election_elapsed: u32,
    election_timeout: u32,
    votes_granted: usize,
    votes_rejected: usize,
    votes_unknown: usize,
    commit_index: u64,
    last_index: u64,
    applied_index: u64,
};

const RaftBatchLeaderTimeoutDiagnostics = struct {
    status: ?RaftBatchLeaderStatusDiagnostics,
    served_group_count: usize,
    peer_route_count: usize,
    sent_frames: usize,
    send_failures: usize,
    retries_scheduled: usize,
    retries_exhausted: usize,
    pending_retry_count: usize,
};

const RaftBatchLeaderTimeoutCaptureContext = struct {
    raft: *antfly.raft.ManagedHttpHostService,
    group_id: u64,
};

fn captureRaftBatchLeaderTimeoutDiagnostics(context: RaftBatchLeaderTimeoutCaptureContext) RaftBatchLeaderTimeoutDiagnostics {
    const transport_host = &context.raft.host.http_host.transport_stack.transport_host;
    const transport_metrics = transport_host.metricsSnapshot();
    const status = if (context.raft.host.http_host.host.raftStatus(context.group_id)) |raft_status|
        RaftBatchLeaderStatusDiagnostics{
            .node_id = raft_status.id,
            .role = raft_status.soft.role,
            .leader_id = raft_status.soft.leader_id,
            .voter_count = raft_status.conf_state.voters.len,
            .term = raft_status.hard.current_term,
            .election_elapsed = raft_status.election_elapsed,
            .election_timeout = raft_status.randomized_election_timeout,
            .votes_granted = raft_status.votes_granted,
            .votes_rejected = raft_status.votes_rejected,
            .votes_unknown = raft_status.votes_unknown,
            .commit_index = raft_status.hard.commit_index,
            .last_index = raft_status.last_index,
            .applied_index = raft_status.applied_index,
        }
    else
        null;
    return .{
        .status = status,
        .served_group_count = transport_host.served_groups.count(),
        .peer_route_count = transport_host.peer_routes.count(),
        .sent_frames = transport_metrics.sent_frames,
        .send_failures = transport_metrics.send_failures,
        .retries_scheduled = transport_metrics.retries_scheduled,
        .retries_exhausted = transport_metrics.retries_exhausted,
        .pending_retry_count = transport_host.pendingRetryCount(),
    };
}

