        .name = try alloc.dupe(u8, "dv_v1"),
        .kind = .dense_vector,
        .doc_count = 787500,
        .node_count = 7131,
        .replay_applied_sequence = 993,
        .replay_target_sequence = 1001001,
        .replay_catch_up_required = true,
    };
    const statuses = try alloc.alloc(runtime_status.LocalTableRuntimeStatus, 1);
    statuses[0] = .{
